import{_ as i,o as s,c as a,ag as t}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Reverse Engineering and Safe Legacy Migration","description":"","frontmatter":{},"headers":[],"relativePath":"en/23-reverse-engineering-and-migration.md","filePath":"en/23-reverse-engineering-and-migration.md"}'),n={name:"en/23-reverse-engineering-and-migration.md"};function o(l,e,r,c,p,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="reverse-engineering-and-safe-legacy-migration" tabindex="-1">Reverse Engineering and Safe Legacy Migration <a class="header-anchor" href="#reverse-engineering-and-safe-legacy-migration" aria-label="Permalink to &quot;Reverse Engineering and Safe Legacy Migration&quot;">​</a></h1><p>SoftForge was built from the ground up for seamless cooperation between human developers and autonomous AI agents. One of the most common tasks when modernizing software is <strong>incorporating capabilities from existing repositories, external projects, or legacy systems</strong>.</p><p>To execute this process without compromising the codebase, SoftForge establishes a <strong>Quarantine Staging Area (<code>staging/</code>)</strong> and enforces the <strong>Pure Functional Extraction</strong> principle.</p><hr><h2 id="_1-core-principles" tabindex="-1">1. Core Principles <a class="header-anchor" href="#_1-core-principles" aria-label="Permalink to &quot;1. Core Principles&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;Legacy / External Repository&quot;] --&gt; B[&quot;Quarantine in staging/ (Git Ignored)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;Functional Specification (EXTRACTION_SPEC.md)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;Vertical Slice Scaffold (slice_scaffold.py)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;Native Rebuild: Backend (FastAPI/SQLAlchemy) + Frontend (Tailwind/Radix)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;Architectural Audit (reverse_engineering.py audit)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G[&quot;Unified Guardrail Verification (verify.py)&quot;]</span></span></code></pre></div><h3 id="_1-1-non-negotiable-quarantine-zero-pollution" tabindex="-1">1.1 Non-Negotiable Quarantine (Zero Pollution) <a class="header-anchor" href="#_1-1-non-negotiable-quarantine-zero-pollution" aria-label="Permalink to &quot;1.1 Non-Negotiable Quarantine (Zero Pollution)&quot;">​</a></h3><ul><li>No external or legacy files should ever be cloned or placed directly into <code>apps/api/</code>, <code>apps/web/</code>, or <code>tools/</code>.</li><li>All legacy codebases must reside in <code>staging/&lt;system_name&gt;/</code>.</li><li>SoftForge&#39;s <code>.gitignore</code> automatically ignores <code>staging/*</code>. Heavy external dependencies (<code>node_modules/</code>, <code>venv/</code>), database dumps, or legacy secrets will <strong>never</strong> be committed.</li></ul><h3 id="_1-2-pure-functional-extraction-zero-stack-distortion" tabindex="-1">1.2 Pure Functional Extraction (Zero Stack Distortion) <a class="header-anchor" href="#_1-2-pure-functional-extraction-zero-stack-distortion" aria-label="Permalink to &quot;1.2 Pure Functional Extraction (Zero Stack Distortion)&quot;">​</a></h3><ul><li>We do not port or &quot;translate&quot; legacy code line-by-line.</li><li>We extract <strong>exclusively business capabilities</strong>: <ul><li>Conceptual data models and fields -&gt; Converted to SQLAlchemy 2.0 inheriting from <code>src.core.database.Base</code>.</li><li>Endpoints and contracts -&gt; Converted to FastAPI and strict Pydantic v2 schemas.</li><li>Calculation rules, validations, and state workflows -&gt; Implemented as pure async functions in <code>service.py</code>.</li></ul></li><li>Foreign backend libraries (Django ORM, Express, TypeORM, Prisma, etc.) are <strong>never</strong> installed or imported.</li></ul><h3 id="_1-3-absolute-preservation-of-the-design-system-zero-ui-distortion" tabindex="-1">1.3 Absolute Preservation of the Design System (Zero UI Distortion) <a class="header-anchor" href="#_1-3-absolute-preservation-of-the-design-system-zero-ui-distortion" aria-label="Permalink to &quot;1.3 Absolute Preservation of the Design System (Zero UI Distortion)&quot;">​</a></h3><ul><li><strong>Strict Prohibition:</strong> NEVER copy legacy stylesheets (<code>.css</code>, <code>.scss</code>, <code>.less</code>), legacy CSS framework classes (Bootstrap, Ant Design, Material-UI, Bulma), or jQuery scripts.</li><li>Every user interface in SoftForge is built from scratch in <code>apps/web/src/features/&lt;slice&gt;/</code> using: <ul><li>Official UI primitives in <code>apps/web/src/components/ui/</code> (Radix UI / Shadcn).</li><li>Tailwind CSS v3 utility classes and active theme tokens.</li><li>Icons from <code>lucide-react</code>.</li><li>Standardized HTTP client (<code>@/lib/api-client</code>).</li></ul></li></ul><hr><h2 id="_2-built-in-tooling-tools-scripts-reverse-engineering-py" tabindex="-1">2. Built-in Tooling (<code>tools/scripts/reverse_engineering.py</code>) <a class="header-anchor" href="#_2-built-in-tooling-tools-scripts-reverse-engineering-py" aria-label="Permalink to &quot;2. Built-in Tooling (\`tools/scripts/reverse_engineering.py\`)&quot;">​</a></h2><p>SoftForge provides a CLI assistant to guide the reverse engineering lifecycle safely:</p><h3 id="_2-1-initialize-a-quarantine-workspace" tabindex="-1">2.1 Initialize a Quarantine Workspace <a class="header-anchor" href="#_2-1-initialize-a-quarantine-workspace" aria-label="Permalink to &quot;2.1 Initialize a Quarantine Workspace&quot;">​</a></h3><p>To set up an isolated staging folder and extraction specification for a new system:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/reverse_engineering.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> legacy-crm</span></span></code></pre></div><p>This command generates:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>staging/legacy-crm/</span></span>
<span class="line"><span>├── .gitignore             # Defense-in-depth isolation</span></span>
<span class="line"><span>├── EXTRACTION_SPEC.md     # Mapping template for models and rules</span></span>
<span class="line"><span>└── source/                # Directory where original source code is placed</span></span></code></pre></div><h3 id="_2-2-list-quarantined-projects" tabindex="-1">2.2 List Quarantined Projects <a class="header-anchor" href="#_2-2-list-quarantined-projects" aria-label="Permalink to &quot;2.2 List Quarantined Projects&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/reverse_engineering.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><h3 id="_2-3-audit-slice-compliance" tabindex="-1">2.3 Audit Slice Compliance <a class="header-anchor" href="#_2-3-audit-slice-compliance" aria-label="Permalink to &quot;2.3 Audit Slice Compliance&quot;">​</a></h3><p>After implementing the vertical slice, verify that all SoftForge invariants are met and no foreign code leaked into the codebase:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/reverse_engineering.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slice_nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><hr><h2 id="_3-step-by-step-execution-workflow" tabindex="-1">3. Step-by-Step Execution Workflow <a class="header-anchor" href="#_3-step-by-step-execution-workflow" aria-label="Permalink to &quot;3. Step-by-Step Execution Workflow&quot;">​</a></h2><ol><li><strong>Initialization:</strong> Run <code>python tools/scripts/reverse_engineering.py init --name &lt;system&gt;</code>.</li><li><strong>Load Legacy Code:</strong> Copy files or clone the legacy repo into <code>staging/&lt;system&gt;/source/</code>.</li><li><strong>Map Domain &amp; Rules:</strong> Fill out <code>staging/&lt;system&gt;/EXTRACTION_SPEC.md</code> mapping entities, endpoints, business rules, and user journeys.</li><li><strong>Scaffold Slice:</strong> Generate the vertical slice skeleton:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/slice_scaffold.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slice_nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li><li><strong>Backend Implementation:</strong><ul><li>Update <code>models.py</code> with typed columns, <code>Base</code> inheritance, and <code>workspace_id</code>.</li><li>Configure strict Pydantic v2 DTOs in <code>schemas.py</code>.</li><li>Implement business logic in <code>service.py</code> using <code>AsyncSession</code>.</li><li>Protect routes in <code>router.py</code> using <code>require_workspace_role(...)</code>.</li><li>Write full integration tests in <code>tests/test_&lt;slice_name&gt;_slice.py</code>.</li></ul></li><li><strong>Frontend Implementation:</strong><ul><li>Create feature directory in <code>apps/web/src/features/&lt;slice_name&gt;/</code>.</li><li>Build UI exclusively using SoftForge components (<code>Card</code>, <code>Button</code>, <code>Table</code>, etc.).</li></ul></li><li><strong>Audit &amp; Verification:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/reverse_engineering.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slice_nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/export_openapi.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/verify.py</span></span></code></pre></div></li><li><strong>Completion:</strong> The <code>staging/&lt;system&gt;/</code> folder can be kept locally for reference or removed, with zero risk to the Git repository or production builds.</li></ol>`,28)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
